    const r=getByKey('12');r.f.开始日期='2026-10-08';
    for(const e of db.employees){e.hrBalance={annual:e.annualBalance,held:0,carry:0,comp:{平时:0,周末:0,节假日:0},compExpiry:'2026-12-31'};}
