  function seedOvertimeHistory(){[['2026-09-02','18:00','20:00'],['2026-09-09','18:00','20:00']].forEach((cfg,i)=>{const [day,st,et]=cfg;const ot=createRecord('14','EMP-2026-018');ot.id='HR-OT-HIST-'+(i+1);ot.items=[{姓名:employee('EMP-2026-018')?.name||'李明',加班类型:'平时',加班事由:'生产支持',加班开始日期时间:day+'T'+st,加班结束日期时间:day+'T'+et,加班时长:2,加班处置:'换补休'}];ot.stage=def('14').steps.length;ot.checks={};HrBusiness.ensure(ot);store.records.push(ot);});}
  function recomputeCompBalances(){for(const e of db.employees){if(!e.hrBalance)continue;const comp={'平时':0,'周末':0,'节假日':0};for(const r of store.records){if(r.employeeId!==e.id||!done(r))continue;if(r.key==='14'){for(const row of HrBusiness.ensure(r).rows){const c=row[1],h=Number(row[5])||0;if(comp[c]!==undefined&&row[6]==='换补休')comp[c]+=h;}}if(r.key==='15'&&!r.historical){const c=r.f.来源类别,h=Number(r.f.小时数)||(Number(r.f.天数)||0)*8;if(comp[c]!==undefined)comp[c]=Math.max(0,comp[c]-h);}}e.hrBalance.comp=comp;}}
