    if(r.key==='10'&&r.f.离岗开始日期&&r.f.离岗结束日期&&r.f.离岗结束日期<r.f.离岗开始日期)return '离岗结束日期不能早于离岗开始日期';
    if(r.key==='11'&&(!r.items.length||r.items.some(x=>!x.变更前信息||!x.变更后信息||!x.变更原因)))return '变更明细须填写变更前信息、变更后信息与变更原因';
