  function archiveTable(rs){return table(['序号','来源单据','业务结果','版本 / 日期','摘要'],rs.map((a,i)=>[i+1,btn(a.source,`HrWorkspace.open('${a.source}')`,'link'),esc(a.kind),'V'+a.version+' / '+a.time,esc(HrBusiness.format(a.detail))]));}
