  function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function file(id,save){const r=get();if(!visible(r))return fail('无查看权限');const f=r.files.find(f=>f.id===id);if(!f)return;const blob=f.blob||new Blob([f.content],{type:'text/plain;charset=utf-8'});if(save)return download(f.name,blob);openModal('材料预览',f.content?`<pre class="hw-pre">${esc(f.content)}</pre>`:`<p>${esc(f.name)} · 本地文件，${blob.size}字节</p><p>请下载后使用相应阅读器查看。</p>`,btn('关闭',"closeModal()")+btn('下载文件',`HrWorkspace.file('${id}',true)`));}
  async function upload(f){const r=get();if(!f||!visible(r)||!(canEdit(r)||canAct(r)))return fail('当前不能上传');if(f.size>10*1024*1024)return fail('演示附件限10MB以内');r.files.push({id:'FILE-'+(++sequence),name:f.name,blob:f,content:f.type.startsWith('text/')?await f.text():null,version:r.version,time:date});log(r,'上传附件',f.name);render();}
  function syncOrigin(id){const e=employee(id),dept=document.querySelector('#hw-origin-dept'),mgr=document.querySelector('#hw-leave-manager'),comp=document.querySelector('#hw-comp-hours'),annual=document.querySelector('#hw-annual-days'),hand=document.querySelector('#hw-handover');if(dept)dept.value=e?.org||'';if(mgr)mgr.value=e?.manager||'';if(comp||annual){const lb=leaveBalance(e);if(comp)comp.value=lb.comp;if(annual)annual.value=lb.annual;}if(hand&&e&&hand.value===e.name){const other=db.employees.find(x=>x.name!==e.name);if(other)hand.value=other.name;}if(['22','23','26','27'].includes(ui.edit?.key)){for(const [k,v] of [['员工姓名',e?.name],['所属部门',e?.org],['岗位',e?.position]]){const n=document.querySelector('[name="'+k+'"]');if(n)n.value=v||'';}}}
  function leaveBalance(e){const b=e?.hrBalance;if(!b)return{comp:'',annual:''};const p=Number(b.comp?.平时)||0,w=Number(b.comp?.周末)||0,h=Number(b.comp?.节假日)||0;const total=p+w+h;const parts=[];if(p)parts.push('平时'+p);if(w)parts.push('周末'+w);if(h)parts.push('节假日'+h);return{comp:total+'小时'+(parts.length?'（'+parts.join(' + ')+'）':''),annual:Math.max(0,Number(b.annual||0)-Number(b.held||0))+'天'};}
  function syncOnboard(id){const e=employee(id),dept=document.querySelector('#hw-dept'),post=document.querySelector('#hw-post'),status=document.querySelector('#hw-emp-status'),no=document.querySelector('#hw-contract-no');if(dept)dept.value=e?.org||'';if(post)post.value=e?.position||'';if(status)status.value=e?.status||'';if(no)no.value=e?.contractNo&&e.contractNo!=='待生成'?e.contractNo:'';}
  function syncEmployee(name){const e=db.employees.find(x=>x.name===name);if(!e)return;const set=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v;};set('hw-emp-dept',e.org);set('hw-emp-post',e.position);set('hw-emp-manager',e.manager||'');set('hw-emp-hiredate',e.hireDate||'');}
  function leaveDays(a,b){if(!a||!b)return '';const d=Math.round((new Date(b)-new Date(a))/86400000)+1;return d>0?d+'天':'';}
  function daysInclusive(a,b){if(!a||!b)return '';const d=Math.round((new Date(b)-new Date(a))/86400000)+1;return d>0?String(d):'';}
  function overtimeHours(a,b){if(!a||!b)return '';const h=(new Date(b)-new Date(a))/3600000;return Number.isFinite(h)&&h>0?String(Math.round(h*100)/100):'0';}
  function syncOvertimeHours(){const a=document.getElementById('hw-ot-start')?.value,b=document.getElementById('hw-ot-end')?.value,out=document.getElementById('hw-ot-hours');if(out)out.value=overtimeHours(a,b);}
  function leaveDurationDays(a,b){if(!a||!b)return '';const d=Math.round((new Date(b)-new Date(a))/86400000)+1;return d>0?String(d):'0';}
  function syncLeaveDuration(){const a=document.getElementById('hw-leave-start12')?.value,b=document.getElementById('hw-leave-end12')?.value,out=document.getElementById('hw-leave-days12');if(out)out.value=leaveDurationDays(a,b);}
