  function syncRow(sel){const row=sel.closest('tr'),e=db.employees.find(x=>x.name===sel.value);if(!row||!e)return;const set=(k,v)=>{const el=row.querySelector('[data-item="'+k+'"]');if(el)el.value=v;};set('调出公司','精美');set('调入公司','精美');set('调出部门',e.org);set('调入部门',e.org);set('调出岗位',e.position);set('调入岗位',e.position);}
