  function view(){if(state.page==='hr-due')return HrBusiness.dueView();if(state.page==='hr')return home();if(['hrCatalog','hrDomain','hrSample'].includes(state.page)){if(state.page==='hrSample'){const idx=db.hrSamples.findIndex(x=>x.id===state.hrSampleId);ui.key=defs[idx]?.key||'01';}else ui.key=null;return listView();}if(state.page==='hr-list')return listView();if(state.page==='hr-record')return detail();if(state.page==='hr-edit')return editView();if(state.page==='hr-balances')return balancesView();if(state.page==='hr-runs')return shell(boundary()+runTable(store.runs.filter(x=>visible(get(x.source)))),'人事接口与补偿','模拟人员、岗位、期间与业务版本对账；不调用外部系统');return null;}
